{
  "core_question": "Should a self‑insured employer add GLP‑1 weight‑management therapy to its benefits, and if so, how should it control utilization and what is the projected three‑year budget impact?",
  "rationale": "The decision requires clinical evidence on efficacy, uptake, persistence, and cost offsets; legal analysis of ERISA/ADA compliance and discrimination risk; and financial modeling of budget impact under uncertain parameters.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "Based on current clinical evidence up to 2026, what is the expected efficacy of GLP‑1 agents for weight management, typical uptake rates among eligible patients, persistence beyond one year, and potential downstream medical cost offsets that a self‑insured employer could anticipate?",
    "legal": "Under ERISA and applicable federal anti‑discrimination laws (e.g., ADA, EEOC), what are the key legal considerations an employer must address when deciding to cover GLP‑1 agents for weight management, including any obligations or risks related to coverage decisions, utilization controls, and potential discrimination claims?",
    "finance": "Assuming a self‑insured employer with 4,100 covered lives, estimate a three‑year budget impact of adding GLP‑1 coverage at $1,050 monthly net cost per treated member, incorporating plausible ranges for uptake (e.g., 5–15%), persistence rates, and potential medical offset costs; provide the calculation methodology."
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Recent FDA approvals of GLP‑1 agents for weight management, evolving clinical guidelines on obesity treatment, and post‑2024 price changes or rebate structures may affect efficacy estimates, uptake rates, and cost calculations."
}
